"""Runs queries.sql against churn.db, writes out/*.csv, checks the roll-forward adds up, draws the charts."""
import sqlite3, csv, re, numpy as np, pandas as pd
import matplotlib; matplotlib.use("Agg"); import matplotlib.pyplot as plt
db = sqlite3.connect("churn.db"); sql = open("queries.sql").read()
for name, body in re.findall(r"-- name: (\w+)\n(.*?)(?=\n-- Q\d|\Z)", sql, re.S):
    cur = db.execute(body); rows = cur.fetchall(); 
    with open(f"out/{name}.csv", "w", newline="") as fh:
        w = csv.writer(fh); w.writerow([d[0] for d in cur.description]); w.writerows(rows)
r = pd.read_csv("out/mrr_rollforward.csv")
assert ((r.opening_mrr + r.new_mrr - r.churned_mrr) == r.closing_mrr).all(), "MRR roll-forward does not reconcile"
assert db.execute("SELECT COUNT(*) FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.signup_date<>c.signup_date").fetchone()[0] == 0
print("checks passed; closing MRR Dec 2025:", r.closing_mrr.iloc[-1])
plt.rcParams.update({"font.size": 10, "axes.spines.top": False, "axes.spines.right": False})
FOOT = "SYNTHETIC DEMO DATA generated by generate_data.py (6,040 invented customers). Not a real business."
c = pd.read_csv("out/cohort_retention.csv"); piv = c.pivot(index="cohort", columns="month_n", values="retention_pct")
fig, ax = plt.subplots(figsize=(10, 6.2)); im = ax.imshow(piv.values, cmap="YlGnBu", aspect="auto", vmin=0, vmax=100)
ax.set_yticks(range(0, len(piv), 2)); ax.set_yticklabels([x[:7] for x in piv.index[::2]]); ax.set_xticks(range(0, 24, 2)); ax.set_xlabel("Months since signup month"); ax.set_ylabel("Signup cohort")
ax.set_title("Share of each cohort still subscribed, by month since signup (%)", loc="left"); fig.colorbar(im, ax=ax, shrink=.8)
fig.text(.01, .01, FOOT, fontsize=8, color="#555"); fig.tight_layout(rect=(0, .03, 1, 1)); fig.savefig("out/cohort_retention.png", dpi=150); plt.close(fig)
fig, ax = plt.subplots(figsize=(10, 5.2)); x = np.arange(len(r)); ax.bar(x, r.new_mrr, color="#2f7f6f", label="New MRR"); ax.bar(x, -r.churned_mrr, color="#c46a5a", label="Churned MRR")
ax2 = ax.twinx(); ax2.plot(x, r.closing_mrr, c="#251f21", lw=2, label="Closing MRR"); ax2.spines["right"].set_visible(True); ax2.set_ylabel("Closing MRR (USD)")
ax.set_xticks(x[::2]); ax.set_xticklabels([m[:7] for m in r.month[::2]], rotation=45); ax.set_ylabel("Monthly MRR movement (USD)"); ax.set_title("MRR roll-forward: new vs churned, and closing MRR", loc="left")
h1, l1 = ax.get_legend_handles_labels(); h2, l2 = ax2.get_legend_handles_labels(); ax.legend(h1 + h2, l1 + l2, frameon=False, loc="upper left")
fig.text(.01, .01, FOOT, fontsize=8, color="#555"); fig.tight_layout(rect=(0, .03, 1, 1)); fig.savefig("out/mrr_rollforward.png", dpi=150); plt.close(fig)
s = pd.read_csv("out/churn_by_segment.csv"); p = s.pivot(index="plan", columns="channel", values="monthly_churn_pct").loc[["Starter", "Pro", "Team"]]
fig, ax = plt.subplots(figsize=(9, 4.6)); w = .2
for i, ch in enumerate(p.columns): ax.bar(np.arange(3) + i * w - 1.5 * w, p[ch], w, label=ch)
ax.set_xticks(range(3)); ax.set_xticklabels(p.index); ax.set_ylabel("Monthly churn (% of customer-months)"); ax.set_title("Monthly churn by plan and acquisition channel", loc="left"); ax.legend(frameon=False, ncol=4)
fig.text(.01, .01, FOOT, fontsize=8, color="#555"); fig.tight_layout(rect=(0, .04, 1, 1)); fig.savefig("out/churn_by_segment.png", dpi=150); plt.close(fig)
print(p.round(2)); print(piv.iloc[0, [0, 1, 3, 6, 12, 23]].round(1).tolist(), piv.iloc[12, [0, 1, 3, 6, 11]].round(1).tolist())
print(r.tail(3).to_string())
